CATALOG=[
{"id":"CVE-2023-39910","title":"Milk Sad — Libbitcoin Explorer bx seed weak entropy","chain":"Bitcoin / BIP39-compatible seed material","status":"historical-confirmed","affected":"Libbitcoin Explorer 3.0.0–3.6.0 when using bx seed; earlier sx/bx variants reported on some systems require case-specific verification.","root_cause":"Mersenne Twister mt19937 restricted effective entropy to 32 bits regardless of requested settings.","still_relevant":"Previously generated seeds remain exposed. Researchers report 3.8.0 removed the problematic command; upgrading does not repair old seeds.","sources":["https://nvd.nist.gov/vuln/detail/CVE-2023-39910","https://milksad.info/faq.html","https://github.com/libbitcoin/libbitcoin-explorer/blob/20eba4db9a8a3476949d6fd08a589abda7fde3e3/src/commands/seed.cpp#L44"]},
{"id":"CVE-2023-31290","title":"Trust Wallet Browser Extension — 32-bit MT19937 entropy","chain":"Ethereum, Solana and other assets supported by the affected Trust Wallet browser extension","status":"historical-confirmed","affected":"Trust Wallet Core before 3.1.1; browser extension versions 0.0.172–0.0.182. Fixed in Core 3.1.1 / extension 0.0.183. Applies to affected browser-extension WASM wallet creation, not every Trust Wallet platform.","root_cause":"The WASM random generator used MT19937 seeded from one 32-bit value, limiting generated mnemonic entropy to 32 bits.","still_relevant":"Previously generated wallets in the affected version window remain at risk even after upgrading. Newer versions are not presumed vulnerable; validate platform and build lineage.","sources":["https://github.com/advisories/GHSA-pm4f-pggw-8jwc","https://blog.ledger.com/Funds-of-every-wallet-created-with-the-Trust-Wallet-browser-extension-could-have-been-stolen/","https://github.com/trustwallet/wallet-core/compare/3.1.0...3.1.1"]},
{"id":"RANDSTORM-2023","title":"Randstorm — historical browser wallet entropy weaknesses","chain":"Bitcoin and forks / browser-generated wallets","status":"historical-research-disclosure","affected":"BitcoinJS used JSBN SecureRandom until March 2014; Unciphered reports affected derivative browser wallets observed as generated during 2011–2015. Exact wallet/product versions must be verified individually.","root_cause":"A type error could bypass window.crypto entropy collection in some JSBN SecureRandom implementations, falling back to Math.random and timer-derived entropy; older browsers could seed Math.random from time.","still_relevant":"Potentially relevant to wallets generated by affected historical software; not a universal Bitcoin flaw. Randstorm has no single CVE identifier.","sources":["https://www.unciphered.com/disclosure-of-vulnerable-bitcoin-wallet-library-2/","https://github.com/RandstormBTC/randstorm"]}
]
def seed_catalog(store):
 for item in CATALOG: store.upsert_vulnerability(item)
